        _get_md_from_url(
            'https://raw.githubusercontent.com/usnistgov/oscal-content/master/nist.gov/SP800-53/rev4/json/NIST_SP-800-53_rev4_catalog.json'
        )
        == 'NIST_SP-800-53_rev4_catalog.md'
    );;
}

